async function setTab(tab){if(selfMode&&['doe-rules','subjects'].includes(tab))return;currentTab=tab;if(tab==='history')UCVM.logs($('faculty-audit'),{includeFaculty:true,profile:currentProfile});if(tab==='sessional')loadAuxOnce();document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const name of ['lookup','summary','roles','doe-rules','subjects','sessional','database','history']){const view=$(`${name}-view`);if(view)view.classList.toggle('hidden',tab!==name)}try{if(tab==='summary'){ $('sync-status').textContent='Loading teaching summary…';await ensureAdminDataset();await loadDoeSummaryList()}else if(['roles','database'].includes(tab)){ $('sync-status').textContent='Loading full faculty data…';await ensureFullFaculty()}else if(tab==='doe-rules'){ $('sync-status').textContent='Loading DOE policy data…';await ensureAdminDataset();await window.UCVM_DOE_POLICY_ADMIN?.load?.();$('sync-status').textContent='DOE policy rules loaded'}else if(tab==='subjects'){await window.UCVM_SUBJECT_CATALOG_ADMIN?.load?.()}}catch(e){console.error(e);toast('Could not load the requested faculty data.',true)}renderActiveTab()}
function subscribeFaculty(){if(facultyUnsubscribe)facultyUnsubscribe();$('sync-status').textContent='Connecting to faculty index…';facultyUnsubscribe=db.collection('settings').doc('faculty_index').onSnapshot(s=>{if(!s.exists||!Array.isArray(s.data().entries)){ensureAdminDataset().catch(e=>{console.error(e);toast('Could not build the faculty index fallback.',true)});return}faculty=s.data().entries.map(indexedFaculty);facultyLoaded=false;updateFilters();updateKpis();updateStatus();renderLookup();window.dispatchEvent(new Event('ucvm:admin-faculty-updated'))},e=>{console.error(e);$('sync-status').textContent='Faculty index read denied';toast('Could not read the faculty index.',true)})}
