function unique(key){return[...new Set(faculty.map(x=>String(getPath(x,key)||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}function fillSelect(id,vals,label){const e=$(id),old=e.value;e.innerHTML=`<option value="">${esc(label)}</option>`+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(vals.includes(old))e.value=old}function updateFilters(){fillSelect('filter-campus',unique('campus'),'All campuses');fillSelect('filter-rank',unique('rank'),'All ranks');const rt=[...new Set(faculty.flatMap(x=>rolesOf(x).map(r=>r.type)))].sort();fillSelect('role-type-filter',rt,'All role types')}
function searchBlob(r){const s=summaryOf(r),w=workloadOf(r),parts=[r.__indexSearch,r.preferredFullName,r.hrFullName,r.ucid,r.email,r.teachingArea,r.teachingAreaEmphasis,r.boardSpecialties,r.boardCertification,r.rank,r.currentTitle,r.campus,r.reportsTo];if(s){parts.push(s.sourceName,s.displayName,s.traineeSummary,s.specialProjectText);for(const x of s.roles||[])parts.push(x.type,x.assignment,x.schedule,x.details)}if(w){parts.push(w.policySource,w.operationalSource);for(const x of w.credits||[])parts.push(x.category,x.assignment,x.quantity,x.rule,x.policyReference);for(const x of w.trainee?.breakdown||[])parts.push(x.category,x.rule,x.policyReference)}for(const x of afcRecordsOf(r))parts.push(x.startDate,x.endDate,x.purpose,x.sourceName);for(const x of liveRows(r)){parts.push(x.session.course,x.session.courseName,x.session.topic,x.session.type,x.session.date,x.assignment.role)}return parts.filter(present).join(' ').toLowerCase()}function matchesSearch(r,q){return!q||searchBlob(r).includes(q)}
function filteredLookup(){const q=norm($('lookup-search').value),camp=$('filter-campus').value,rank=$('filter-rank').value;return faculty.filter(r=>r.active!==false&&matchesSearch(r,q)&&(!camp||r.campus===camp)&&(!rank||r.rank===rank))}
function overrideOf(r){const o=r?.doeOverride2026_27;return o&&numeric(o.value)!==null?o:null}function authoritativeOverrideOf(r){const target=cachedDoeWorksheet(r)?.target||doeListByFaculty.get(String(r?.__id||''))?.target||null,value=numeric(target?.overrideDoe);return value===null?null:{value,reason:String(target?.overrideReason||''),notes:String(target?.overrideNotes||''),source:String(target?.source||'')}}function overrideBadge(r){const o=authoritativeOverrideOf(r)||overrideOf(r);return o?`<span class="override-badge" title="Office DOE Override${o.notes?' · '+esc(o.notes):''}">Override DOE ${Number(o.value).toFixed(2)}%${o.reason?' · '+esc(o.reason):''}</span>`:''}
