function field(label,value,full=false){if(!present(value))return'';return`<div class="field ${full?'full':''}"><div class="field-label">${esc(label)}</div><div class="field-value">${esc(display(value))}</div></div>`}function section(title,body,wide=false){if(!body.trim())return'';return`<section class="section ${wide?'wide':''}"><div class="section-title">${esc(title)}</div><div class="field-grid">${body}</div></section>`}
function prettyDate(v){if(!v)return'—';const d=new Date(v+'T00:00:00');return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'})}function timeBlock(a){return`${a.from||'—'}${a.to?'–'+a.to:''}`}
function roleAmount(x){const out=[];if(present(x.weeks))out.push(`${x.weeks} week(s)`);if(present(x.shifts))out.push(`${x.shifts} shift(s)`);if(present(x.count))out.push(`${x.count} trainee(s)`);if(numeric(x.doe)!==null)out.push(`${Number(x.doe).toFixed(2)}% DOE`);return out.join(' · ')||'—'}function roleDetails(x){return[x.schedule,x.details].filter(present).join(' · ')||'—'}
