function legacySummaryHtml(r,s){if(!s)return'<section class="section wide"><div class="section-title">2026-2027 Teaching Summary</div><div class="no-source">No faculty summary sheet exists for this faculty member in 2026-09-03 - All Faculty Summaries.xlsx.</div></section>';const doe=canonicalDoeEntry(r),live=doe.calculationStatus==='error'?null:numeric(doe.assignedTeachingDOE),sched=numeric(doe.scheduledDOE)||0,fixed=numeric(doe.sourceNonTimetableTeachingDOE),contract=numeric(doe.contractTeachingDOE),target=numeric(doe.effectiveTargetDOE),variance=doe.calculationStatus==='error'?null:numeric(doe.remainingDOE),w=workloadOf(r);const vLabel=doe.calculationStatus==='error'?'DOE unavailable':variance===null?'—':Math.abs(variance)<=.25?'At target':variance>0?`${Math.abs(variance).toFixed(2)}% remaining`:`${Math.abs(variance).toFixed(2)}% over`;return`<section class="section wide"><div class="section-title">2026-2027 Teaching Summary · canonical persisted DOE</div><div class="summary-grid"><div class="summary-card"><div class="summary-card-label">Assigned Teaching DOE</div><div class="summary-card-value">${live===null?'Unavailable':Number(live).toFixed(2)+'%'}</div><div class="summary-card-sub">Persisted scheduled DOE + source-reconciled non-timetable + approved managed-role adjustments</div></div><div class="summary-card"><div class="summary-card-label">Scheduled Teaching DOE</div><div class="summary-card-value">${Number(sched).toFixed(2)}%</div><div class="summary-card-sub">Persisted assignment doeCredit only; no legacy rate inference</div></div><div class="summary-card"><div class="summary-card-label">Non-Timetable / Role DOE</div><div class="summary-card-value">${fixed===null?'—':Number(fixed).toFixed(2)+'%'}</div><div class="summary-card-sub">Source-reconciled role / supervision component</div></div><div class="summary-card"><div class="summary-card-label">Contract Teaching DOE</div><div class="summary-card-value">${doePct(contract)}</div><div class="summary-card-sub">Original contract source remains preserved</div></div><div class="summary-card"><div class="summary-card-label">Effective Target</div><div class="summary-card-value">${doePct(target)}</div><div class="summary-card-sub">${esc(doe.targetSource||'none')} target source</div></div><div class="summary-card"><div class="summary-card-label">Remaining / Over</div><div class="summary-card-value">${esc(vLabel)}</div><div class="summary-card-sub">Target minus Assigned DOE; unavailable if any required DOE is missing</div></div><div class="summary-card"><div class="summary-card-label">Policy Version</div><div class="summary-card-value">${esc(doe.policyVersionId||'—')}</div><div class="summary-card-sub">Calculation status: ${esc(doe.calculationStatus||'unavailable')}</div></div><div class="summary-card"><div class="summary-card-label">Workload Breakdown</div><div class="summary-card-value">${w?'Loaded':'Not loaded'}</div><div class="summary-card-sub">${w?`${(w.credits||[]).length} structured role credits · ${doePct(w.trainee?.rawPolicyOperationalDOE)} raw trainee DOE`:'Import V9.7 private workload JSON'}</div></div></div><div class="workload-formula"><strong>Canonical aggregation:</strong> Assigned Teaching DOE uses persisted DOE credits. ${live!==null&&fixed!==null?`For this faculty member: <strong>${Number(live).toFixed(2)}%</strong> assigned, including <strong>${Number(sched).toFixed(2)}%</strong> scheduled and <strong>${Number(fixed).toFixed(2)}%</strong> source non-timetable before managed-role adjustments.`:''}</div><div class="field-grid">${field('Source sheet',s.sourceSheet)+field('Source Assigned Teaching DOE (B2)',numeric(s.assignedTeachingDOE)===null?'':Number(s.assignedTeachingDOE).toFixed(3)+'%')+field('Source scheduled DOE baseline',numeric(s.sourceScheduledTeachingDOE)===null?'':Number(s.sourceScheduledTeachingDOE).toFixed(3)+'%')+field('Special project',s.specialProjectText,true)+field('Special project DOE',numeric(s.specialProjectDOE)===null?'':s.specialProjectDOE+'%')}</div><div class="aux-note"><strong>Policy transparency:</strong> current policy-engine calculations are explained from immutable stored snapshots below. Missing policy inputs are shown as unavailable instead of being replaced with zero or a legacy local rate.</div></section>${workloadBreakdownHtml(r)}`}
