  const facultyId=String(source.ucid||''),profile=facultyById.get(facultyId)||{},facultyName=profile.preferredFullName||profile.hrFirstLast||profile.hrFullName||source.name||facultyId;
  (Array.isArray(source.records)?source.records:[]).forEach((record,index)=>{if(!/\bCCC\b/i.test(String(record?.purpose||''))||!record?.startDate||!record?.endDate)return;events.push({id:cccScheduleId(`${facultyId}|${record.startDate}|${record.endDate}|${record.sourceRow||index}`),facultyId,facultyName,startDate:String(record.startDate),endDate:String(record.endDate),purpose:'CCC Day'})});
