 events.sort((a,b)=>a.startDate.localeCompare(b.startDate)||a.facultyName.localeCompare(b.facultyName)||a.id.localeCompare(b.id));
 await db.collection('public_schedule').doc('ccc_events').set({events,count:events.length,facultyCount:new Set(events.map(x=>x.facultyId)).size,source:'Sanitized AFC CCC records',updatedBy:currentUser.uid,updatedByName:currentUser.name,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
