function afcHtml(r){const all=afcRecordsOf(r),today=todayDateOnly(),up=all.filter(x=>x.endDate>=today).sort((a,b)=>a.startDate.localeCompare(b.startDate)||a.endDate.localeCompare(b.endDate)),past=all.filter(x=>x.endDate<today).sort((a,b)=>b.endDate.localeCompare(a.endDate)||b.startDate.localeCompare(a.startDate));const current=up.filter(x=>x.startDate<=today&&today<=x.endDate).length,privacy=selfMode?'This is your private Away from Campus / availability record. Other faculty cannot read these details.':'Admin-only HR/availability information imported from AFC Tracker. Timetable SWAP and instructor assignment use these date ranges to flag availability. For privacy, the timetable assignment tools only display AFC as Unavailable; detailed AFC reasons remain in this admin HR archive.';return`<section class="section wide"><div class="section-title">Away from Campus · Availability & HR Archive</div><div class="afc-wrap"><details class="afc-fold" open><summary><span>Current / Upcoming</span><span>${up.length} record${up.length===1?'':'s'}${current?` · ${current} active now`:''}</span></summary>${afcRowsTable(up,'upcoming')}</details><details class="afc-fold"><summary><span>Past · HR Archive</span><span>${past.length} archived</span></summary>${afcRowsTable(past,'past')}</details><div class="afc-privacy">${esc(privacy)}</div></div></section>`}
async function importAfcJson(e){const file=e.target.files?.[0];e.target.value='';if(!file||!requireGeneralImport())return;try{await ensureFullFaculty();const p=JSON.parse(await file.text());if(p.schemaVersion!=='ucvm-away-from-campus-v1-2026-09-03'||!Array.isArray(p.faculty))throw new Error('Please select UCVM_AWAY_FROM_CAMPUS_AFC_2026_27.json from the private AFC package.');if(!confirm(`Replace Away from Campus / AFC records for the faculty directory?\n\nSource: ${p.sourceWorkbook}\nImportable records: ${p.importableRecordCount}\nFaculty with records: ${p.facultyWithRecords}\n\nThis updates availability and the HR archive only. It does not change teaching assignments or DOE.`))return;$('import-afc-btn').disabled=true;$('import-afc-btn').textContent='Importing AFC…';const byId=new Map(p.faculty.map(x=>[String(x.ucid),x]));const del=firebase.firestore.FieldValue.delete();let matched=0,records=0;for(let i=0;i<faculty.length;i+=350){const batch=db.batch();for(const r of faculty.slice(i,i+350)){const src=byId.get(String(r.__id));const patch={awayFromCampusSource:p.sourceWorkbook,awayFromCampusImportedAt:firebase.firestore.FieldValue.serverTimestamp(),awayFromCampusImportedBy:currentUser.uid,updatedBy:currentUser.uid,updatedByName:currentUser.name};if(src&&Array.isArray(src.records)&&src.records.length){patch.awayFromCampusRecords=src.records;matched++;records+=src.records.length}else patch.awayFromCampusRecords=del;batch.set(db.collection(COLLECTION).doc(r.__id),patch,{merge:true})}await batch.commit()}await db.collection(LOG_COLLECTION).add({action:'replace_away_from_campus_afc',sourceWorkbook:p.sourceWorkbook,facultyCount:matched,recordCount:records,duplicateRowsSkipped:p.duplicateRowsSkipped||0,invalidRowsSkipped:p.invalidRowsSkipped||0,changedBy:currentUser.uid,changedByName:currentUser.name,changedAt:firebase.firestore.FieldValue.serverTimestamp()});await syncCccPublicSchedule(p);await reloadAdminDataset();toast(`AFC import complete: ${records} records loaded for ${matched} faculty; the CCC timetable was synchronized.`)}catch(err){console.error(err);toast(`AFC import failed: ${err.message||err}`,true)}finally{$('import-afc-btn').disabled=false;$('import-afc-btn').textContent='Import Away from Campus'}}
function calculationTime(value){if(value&&typeof value.toDate==='function')return value.toDate().toLocaleString('en-CA');const d=new Date(value||'');return Number.isNaN(d.getTime())?String(value||'—'):d.toLocaleString('en-CA')}
function loadDoeCalculationHistory(facultyId){const id=String(facultyId||'');if(selfMode||!id||doeHistoryByFaculty.has(id)||doeHistoryLoading.has(id))return;doeHistoryLoading.add(id);db.collection('doe_calculation_records').where('facultyId','==',id).get().then(snapshot=>{const rows=snapshot.docs.map(d=>({calculationId:d.id,...d.data()})).sort((a,b)=>String(b.calculatedAt?.toDate?.()?.toISOString?.()||b.calculatedAt||'').localeCompare(String(a.calculatedAt?.toDate?.()?.toISOString?.()||a.calculatedAt||'')));doeHistoryByFaculty.set(id,rows);if(selectedId===id){const current=faculty.find(x=>String(x.__id)===id);if(current)renderProfile(current)}}).catch(error=>{console.error('[DOE calculation history]',error);doeHistoryByFaculty.set(id,[])}).finally(()=>doeHistoryLoading.delete(id))}
function doeCalculationHistoryHtml(r){if(selfMode)return'';const id=String(r?.__id||'');if(!doeHistoryByFaculty.has(id)){loadDoeCalculationHistory(id);return'<section class="section wide"><div class="section-title">DOE calculation provenance</div><div class="muted">Loading immutable calculation history…</div></section>'}const rows=doeHistoryByFaculty.get(id)||[];if(!rows.length)return'<section class="section wide"><div class="section-title">DOE calculation provenance</div><div class="muted">No policy-engine calculation records are available yet. Legacy DOE remains visible above but is not back-filled with invented provenance.</div></section>';return`<section class="section wide"><div class="section-title">DOE calculation provenance · immutable snapshots</div><div class="assignment-wrap"><table class="activity-table"><thead><tr><th>Calculated</th><th>Policy / Rule</th><th>Inputs</th><th>Parameters</th><th class="num">Result</th><th>Trigger</th></tr></thead><tbody>${rows.slice(0,100).map(row=>`<tr><td>${esc(calculationTime(row.calculatedAt))}</td><td><strong>${esc(row.policyVersionId||'—')}</strong><div class="muted">${esc(row.ruleKey||row.ruleId||'—')}</div></td><td>${esc(JSON.stringify(row.inputsSnapshot||{}))}</td><td>${esc(JSON.stringify(row.parametersSnapshot||{}))}</td><td class="num">${numeric(row.resultDoe)===null?'Unavailable':Number(row.resultDoe).toFixed(3)+'%'}</td><td>${esc(row.trigger||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}
